import { createChart, getECModel } from '../../core/utHelper';
import { EChartsType } from '../../../../src/echarts';
import { EChartsOption } from '../../../../src/export/option';
import CartesianAxisModel from '../../../../src/coord/cartesian/AxisModel';
import Axis from '../../../../src/coord/Axis';
import OrdinalScale from '../../../../src/scale/Ordinal';
import Model from '../../../../src/model/Model';
import { AxisBaseModel } from '../../../../src/coord/AxisBaseModel';

/**
 * Make a category axis on band, of which the coord extent is `[0, 300]`.
 */
function createBandAxis(): Axis {
    const scale = new OrdinalScale({
        ordinalMeta: ['a', 'b', 'c', 'd', 'e']
    });
    const axis = new Axis('x', scale, [0, 300]);
    axis.type = 'category';
    axis.onBand = true;
    axis.model = new Model({
        type: 'category',
        // Display every label.
        axisLabel: { show: true, interval: 0 },
        // Display every category.
        axisTick: { show: true, interval: 0 }
    }) as unknown as AxisBaseModel;
    return axis;
}

/**
 * Make a category axis of which the ticks are not on band, of which the coord
 * extent is `[0, 300]`.
 */
function createCategoryAxis(opt?: {
    onBand?: boolean,
    alignWithLabel?: boolean,
    interval?: number,
    inverse?: boolean
}): Axis {
    opt = opt || {};
    const scale = new OrdinalScale({
        ordinalMeta: ['a', 'b', 'c', 'd', 'e']
    });
    const axis = new Axis('x', scale, opt.inverse ? [300, 0] : [0, 300]);
    axis.type = 'category';
    axis.onBand = !!opt.onBand;
    axis.inverse = !!opt.inverse;
    axis.model = new Model({
        type: 'category',
        axisLabel: {},
        axisTick: {
            show: true,
            interval: opt.interval != null ? opt.interval : 0,
            alignWithLabel: !!opt.alignWithLabel
        }
    }) as unknown as AxisBaseModel;
    return axis;
}

function coordsOf(axis: Axis, clamp?: boolean): number[] {
    return axis.getTicksCoords({ clamp: clamp }).map(item => item.coord);
}

function expectInsideExtent(axis: Axis, coords: number[]): void {
    const extent = axis.getExtent();
    const min = Math.min(extent[0], extent[1]);
    const max = Math.max(extent[0], extent[1]);
    coords.forEach(function (coord) {
        expect(coord).toBeGreaterThanOrEqual(min - 1e-8);
        expect(coord).toBeLessThanOrEqual(max + 1e-8);
    });
}

describe('axis_ticksInsideExtent', function () {

    it('should keep band ticks inside the axis extent', function () {
        const axis = createBandAxis();

        // All the categories are displayed.
        expect(coordsOf(axis)).toEqual([0, 60, 120, 180, 240, 300]);

        // Narrow the window down (like dataZoom does), while the ticks
        // that were made for the previous window are still there.
        axis.scale.setExtent(2, 4);

        const coords = axis.getTicksCoords();
        const extent = axis.getExtent();
        coords.forEach(function (item) {
            expect(item.coord).toBeGreaterThanOrEqual(extent[0]);
            expect(item.coord).toBeLessThanOrEqual(extent[1]);
        });
        expect(coords.map(item => item.coord)).toEqual([0, 100, 200, 300]);
    });

    it('should clamp band ticks to the axis extent when clamp is specified', function () {
        const axis = createBandAxis();

        expect(coordsOf(axis, true)).toEqual([0, 60, 120, 180, 240, 300]);

        axis.scale.setExtent(2, 4);

        const extent = axis.getExtent();
        const coords = coordsOf(axis, true);
        coords.forEach(function (coord) {
            expect(coord).toBeGreaterThanOrEqual(extent[0]);
            expect(coord).toBeLessThanOrEqual(extent[1]);
        });
        // The extent bounds are always included when clamp is specified.
        expect(coords[0]).toBe(extent[0]);
        expect(coords[coords.length - 1]).toBe(extent[1]);
    });

    it('should keep ticks inside the extent when the ticks are not on band', function () {
        // `boundaryGap: false`, so the ticks are at the categories themselves.
        const axis = createCategoryAxis({ onBand: false });

        expect(coordsOf(axis)).toEqual([0, 75, 150, 225, 300]);

        axis.scale.setExtent(2, 4);
        expectInsideExtent(axis, coordsOf(axis));
        expect(coordsOf(axis)).toEqual([0, 150, 300]);
    });

    it('should keep ticks inside the extent when they are aligned with the labels', function () {
        const axis = createCategoryAxis({ onBand: true, alignWithLabel: true });

        expect(coordsOf(axis)).toEqual([30, 90, 150, 210, 270]);

        axis.scale.setExtent(2, 4);
        expectInsideExtent(axis, coordsOf(axis));
        expect(coordsOf(axis)).toEqual([50, 150, 250]);
    });

    it('should keep ticks inside the extent of an inversed axis', function () {
        const axis = createCategoryAxis({ onBand: true, inverse: true });

        axis.scale.setExtent(2, 4);
        expectInsideExtent(axis, coordsOf(axis));
        expectInsideExtent(axis, coordsOf(axis, true));
    });

    it('should keep ticks inside the extent when only the max side is narrowed', function () {
        const axis = createBandAxis();

        expect(coordsOf(axis)).toEqual([0, 60, 120, 180, 240, 300]);

        axis.scale.setExtent(0, 2);
        expectInsideExtent(axis, coordsOf(axis));
        expect(coordsOf(axis)).toEqual([0, 100, 200, 300]);
        expectInsideExtent(axis, coordsOf(axis, true));
    });

    it('should keep ticks inside the extent when a tick interval is specified', function () {
        // Ticks at the categories 0, 2 and 4.
        const axis = createCategoryAxis({ onBand: true, interval: 1 });

        expect(coordsOf(axis)).toEqual([0, 120, 240, 300]);

        axis.scale.setExtent(0, 2);
        expectInsideExtent(axis, coordsOf(axis));
        expectInsideExtent(axis, coordsOf(axis, true));
    });

    it('should keep the labels inside the extent as well', function () {
        const axis = createBandAxis();

        expect(axis.getViewLabels().length).toEqual(5);

        axis.scale.setExtent(2, 4);

        const labels = axis.getViewLabels();
        const scaleExtent = axis.scale.getExtent();
        expect(labels.length).toEqual(3);
        expectInsideExtent(axis, labels.map(function (labelItem) {
            expect(labelItem.tickValue).toBeGreaterThanOrEqual(scaleExtent[0]);
            expect(labelItem.tickValue).toBeLessThanOrEqual(scaleExtent[1]);
            return axis.dataToCoord(labelItem.tickValue);
        }));
    });

    it('should make the ticks again when the window is widened', function () {
        const axis = createBandAxis();

        axis.scale.setExtent(2, 4);
        expect(coordsOf(axis)).toEqual([0, 100, 200, 300]);

        // All the categories are in the window again.
        axis.scale.setExtent(0, 4);
        expect(coordsOf(axis)).toEqual([0, 60, 120, 180, 240, 300]);
    });

    it('should not overflow the grid when dataZoom is used', function () {
        const chart: EChartsType = createChart({ width: 400, height: 300 });
        const categories: string[] = [];
        const values: number[] = [];
        for (let i = 0; i < 20; i++) {
            categories.push('cat' + i);
            values.push(i % 7 + 1);
        }
        chart.setOption({
            xAxis: { type: 'category', data: categories },
            yAxis: {},
            dataZoom: [{ type: 'inside', start: 0, end: 100 }],
            series: [{ type: 'bar', data: values }]
        } as EChartsOption);

        function checkTicksInsideGrid() {
            const axisModel = getECModel(chart).getComponent('xAxis', 0) as CartesianAxisModel;
            const axis = axisModel.axis;
            const extent = axis.getExtent();
            const ticksCoords = axis.getTicksCoords();
            expect(ticksCoords.length).toBeGreaterThan(1);
            ticksCoords.forEach(function (item) {
                // Tolerance for the rounding error of the coord calculation.
                expect(item.coord).toBeGreaterThanOrEqual(extent[0] - 1e-8);
                expect(item.coord).toBeLessThanOrEqual(extent[1] + 1e-8);
            });
            // The band ticks always cover the whole axis.
            expect(ticksCoords[0].coord).toBeCloseTo(extent[0], 6);
            expect(ticksCoords[ticksCoords.length - 1].coord).toBeCloseTo(extent[1], 6);
        }

        checkTicksInsideGrid();

        chart.dispatchAction({ type: 'dataZoom', start: 23, end: 61 });
        checkTicksInsideGrid();

        chart.dispatchAction({ type: 'dataZoom', start: 71, end: 100 });
        checkTicksInsideGrid();

        chart.dispose();
    });

});

