 60	    labels: InnerTickLabelCache<InnerLabelCachedVal>
 61	    ticks: InnerTickLabelCache<InnerTickCachedVal>
 62	    autoInterval: number
 63	    lastAutoInterval: number
 64	    lastTickCount: number
