 71	export function createAxisLabels(axis: Axis): {
 72	    labels: {
 73	        level?: number,
 74	        formattedLabel: string,
 75	        rawLabel: string,
 76	        tickValue: number
 77	    }[],
 78	    labelCategoryInterval?: number
 79	} {
 80	    const custom = makeAxisLabelsFromCustomValues(axis);
 81	    if (custom) {
 82	        return custom;
 83	    }
 84	    // Only ordinal scale support tick interval
 85	    return axis.type === 'category'
 86	        ? makeCategoryLabels(axis)
 87	        : makeRealNumberLabels(axis);
 88	}
 89	
 90	/**
 91	 * @param {module:echats/coord/Axis} axis
 92	 * @param {module:echarts/model/Model} tickModel For example, can be axisTick, splitLine, splitArea.
 93	 * @return {Object} {
 94	 *     ticks: Array.<number>
 95	 *     tickCategoryInterval: number
 96	 * }
 97	 */
 98	export function createAxisTicks(axis: Axis, tickModel: AxisBaseModel): {
 99	    ticks: number[],
100	    tickCategoryInterval?: number
101	} {
102	    const customValues = (tickModel as unknown as Model<AxisTickOption>).get('customValues');
103	    if (customValues) {
104	        return { ticks: parseCustomValues(axis, customValues) };
105	    }
106	    // Only ordinal scale support tick interval
107	    return axis.type === 'category'
108	        ? makeCategoryTicks(axis, tickModel)
109	        : {ticks: zrUtil.map(axis.scale.getTicks(), tick => tick.value) };
110	}
111	
112	/**
113	 * Parse the user specified `customValues` to the inner tick values
114	 * (the ordinal number for ordinal scale, the numeric value otherwise),
115	 * and discard the values that are out of the axis extent.
116	 */
117	function parseCustomValues(axis: Axis, customValues: (number | string | Date)[]): number[] {
118	    const scale = axis.scale;
119	    const extent = scale.getExtent();
120	    const result: number[] = [];
121	    zrUtil.each(customValues, function (val) {
122	        const tickValue = scale.parse(val);
123	        // NaN is filtered out by the comparison as well.
124	        if (tickValue >= extent[0] && tickValue <= extent[1]) {
125	            result.push(tickValue);
126	        }
127	    });
128	    return result;
129	}
