131	/**
132	 * Make labels at the `axisLabel.customValues` if specified,
133	 * otherwise return `null` to keep the default behavior.
134	 */
135	function makeAxisLabelsFromCustomValues(axis: Axis): ReturnType<typeof createAxisLabels> {
136	    const labelModel = axis.getLabelModel();
137	    const customValues = labelModel.get('customValues');
138	    if (!customValues) {
139	        return null;
140	    }
141	    // Labels are always made by the normal label formatter, so that,
142	    // for example, time axis labels are formatted as expected.
143	    const labelFormatter = makeLabelFormatter(axis);
144	    return {
145	        labels: zrUtil.map(parseCustomValues(axis, customValues), function (tickValue, idx) {
146	            const tickObj = { value: tickValue };
147	            return {
148	                formattedLabel: labelFormatter(tickObj, idx),
149	                rawLabel: axis.scale.getLabel(tickObj),
150	                tickValue: tickValue
151	            };
152	        })
153	    };
154	}
