156	function makeCategoryLabels(axis: Axis) {
157	    const labelModel = axis.getLabelModel();
158	    const result = makeCategoryLabelsActually(axis, labelModel);
159	
160	    return (!labelModel.get('show') || axis.scale.isBlank())
