165	function makeCategoryLabelsActually(axis: Axis, labelModel: Model<AxisBaseOption['axisLabel']>) {
166	    const labelsCache = getListCache(axis, 'labels');
167	    const scaleExtent = axis.scale.getExtent();
168	    const optionLabelInterval = getOptionCategoryInterval(labelModel);
169	    const result = listCacheGet(labelsCache, optionLabelInterval as CacheKey, scaleExtent);
170	
171	    if (result) {
172	        return result;
173	    }
174	
175	    let labels;
176	    let numericLabelInterval;
177	
178	    if (zrUtil.isFunction(optionLabelInterval)) {
179	        labels = makeLabelsByCustomizedCategoryInterval(axis, optionLabelInterval);
180	    }
181	    else {
182	        numericLabelInterval = optionLabelInterval === 'auto'
183	            ? makeAutoCategoryInterval(axis) : optionLabelInterval;
184	        labels = makeLabelsByNumericCategoryInterval(axis, numericLabelInterval);
185	    }
186	
187	    // Cache to avoid calling interval function repeatedly.
188	    return listCacheSet(labelsCache, optionLabelInterval as CacheKey, scaleExtent, {
189	        labels: labels, labelCategoryInterval: numericLabelInterval
190	    });
191	}
