193	function makeCategoryTicks(axis: Axis, tickModel: AxisBaseModel) {
194	    const ticksCache = getListCache(axis, 'ticks');
195	    const scaleExtent = axis.scale.getExtent();
196	    const optionTickInterval = getOptionCategoryInterval(tickModel);
197	    const result = listCacheGet(ticksCache, optionTickInterval as CacheKey, scaleExtent);
198	
199	    if (result) {
200	        return result;
201	    }
202	
203	    let ticks: number[];
204	    let tickCategoryInterval;
205	
206	    // Optimize for the case that large category data and no label displayed,
207	    // we should not return all ticks.
208	    if (!tickModel.get('show') || axis.scale.isBlank()) {
209	        ticks = [];
210	    }
211	
212	    if (zrUtil.isFunction(optionTickInterval)) {
213	        ticks = makeLabelsByCustomizedCategoryInterval(axis, optionTickInterval, true);
214	    }
215	    // Always use label interval by default despite label show. Consider this
216	    // scenario, Use multiple grid with the xAxis sync, and only one xAxis shows
217	    // labels. `splitLine` and `axisTick` should be consistent in this case.
218	    else if (optionTickInterval === 'auto') {
