/* THROWAWAY REVIEW TEST - DELETE */
import { createChart, getECModel } from '../../core/utHelper';
import { EChartsType } from '../../../../src/echarts';
import { EChartsOption } from '../../../../src/export/option';
import CartesianAxisModel from '../../../../src/coord/cartesian/AxisModel';
import Axis from '../../../../src/coord/Axis';
import OrdinalScale from '../../../../src/scale/Ordinal';
import * as builder from '../../../../src/coord/axisTickLabelBuilder';

type Counters = {
    createAxisTicks: number,
    createAxisLabels: number,
    getTicksCoords: number,
    getViewLabels: number,
    // actual work: getLabel is called once per produced label
    ordinalGetLabel: number,
    // actual work: auto interval computation
    calcCategoryInterval: number,
    // actual work: text measuring inside calculateCategoryInterval
    labelFormatterCalls: number
};

let counters: Counters;
const callers: string[] = [];

function resetCounters() {
    counters = {
        createAxisTicks: 0,
        createAxisLabels: 0,
        getTicksCoords: 0,
        getViewLabels: 0,
        ordinalGetLabel: 0,
        calcCategoryInterval: 0,
        labelFormatterCalls: 0
    };
    callers.length = 0;
}

function shortStack(skip: number): string {
    const e = new Error();
    const lines = (e.stack || '').split('\n').slice(skip + 1, skip + 5);
    return lines.map(l => l.trim().replace(/\s*\(.*$/, '')).join(' <- ');
}

// ---- install instrumentation -------------------------------------------------
const origCreateTicks = builder.createAxisTicks;
const origCreateLabels = builder.createAxisLabels;
const origCalcInterval = builder.calculateCategoryInterval;
(builder as any).createAxisTicks = function (...args: any[]) {
    counters && counters.createAxisTicks++;
    callers.push('createAxisTicks: ' + shortStack(1));
    return (origCreateTicks as any).apply(this, args);
};
(builder as any).createAxisLabels = function (...args: any[]) {
    counters && counters.createAxisLabels++;
    callers.push('createAxisLabels: ' + shortStack(1));
    return (origCreateLabels as any).apply(this, args);
};
(builder as any).calculateCategoryInterval = function (...args: any[]) {
    counters && counters.calcCategoryInterval++;
    return (origCalcInterval as any).apply(this, args);
};

const origGetTicksCoords = Axis.prototype.getTicksCoords;
Axis.prototype.getTicksCoords = function (...args: any[]) {
    counters && counters.getTicksCoords++;
    return (origGetTicksCoords as any).apply(this, args);
};
const origGetViewLabels = Axis.prototype.getViewLabels;
Axis.prototype.getViewLabels = function (...args: any[]) {
    counters && counters.getViewLabels++;
    return (origGetViewLabels as any).apply(this, args);
};
const origOrdinalGetLabel = OrdinalScale.prototype.getLabel;
OrdinalScale.prototype.getLabel = function (...args: any[]) {
    counters && counters.ordinalGetLabel++;
    return (origOrdinalGetLabel as any).apply(this, args);
};

// find the makeInner store on an axis
function innerStore(axis: any): any {
    for (const k in axis) {
        if (k.indexOf('__ec_inner_') === 0) {
            const v = axis[k];
            if (v && (v.labels || v.ticks)) {
                return v;
            }
        }
    }
    return null;
}

function dumpCache(axis: any) {
    const s = innerStore(axis);
    if (!s) {
        return 'no cache';
    }
    const f = (arr: any[]) => (arr || []).map((it: any) =>
        `key=${it.key} ext=[${it.scaleExtent0},${it.scaleExtent1}]`).join(' | ');
    return `ticks(${(s.ticks || []).length}): ${f(s.ticks)} ;; labels(${(s.labels || []).length}): ${f(s.labels)}`
        + ` ;; autoInterval=${s.autoInterval}`;
}

function xAxisOf(chart: EChartsType): Axis {
    return (getECModel(chart).getComponent('xAxis', 0) as CartesianAxisModel).axis;
}

function makeOption(n: number): EChartsOption {
    const categories: string[] = [];
    const values: number[] = [];
    for (let i = 0; i < n; i++) {
        categories.push('category-' + i);
        values.push(i % 7 + 1);
    }
    return {
        grid: { containLabel: true },
        xAxis: { type: 'category', data: categories, axisLabel: { interval: 'auto' } },
        yAxis: {},
        dataZoom: [{ type: 'inside', start: 0, end: 100 }],
        series: [{ type: 'line', data: values }]
    } as EChartsOption;
}

describe('review: tick/label cache keyed by scale extent', function () {

    it('Q1: count computations in one full render', function () {
        const chart = createChart({ width: 500, height: 400 });
        resetCounters();
        chart.setOption(makeOption(60));
        // eslint-disable-next-line
        console.log('=== Q1 initial render counters ===', JSON.stringify(counters, null, 1));
        // eslint-disable-next-line
        console.log('=== Q1 initial render callers ===\n' + callers.join('\n'));
        const axis = xAxisOf(chart);
        // eslint-disable-next-line
        console.log('=== Q1 cache after initial render ===\n' + dumpCache(axis));
        // eslint-disable-next-line
        console.log('=== Q1 scale extent ===', JSON.stringify(axis.scale.getExtent()));

        resetCounters();
        chart.dispatchAction({ type: 'dataZoom', start: 20, end: 60 });
        // eslint-disable-next-line
        console.log('=== Q1 after dataZoom counters ===', JSON.stringify(counters, null, 1));
        // eslint-disable-next-line
        console.log('=== Q1 after dataZoom callers ===\n' + callers.join('\n'));
        const axis2 = xAxisOf(chart);
        // eslint-disable-next-line
        console.log('=== Q1 same axis object as before? ===', axis2 === axis);
        // eslint-disable-next-line
        console.log('=== Q1 cache after dataZoom ===\n' + dumpCache(axis2));
        chart.dispose();
    });

    it('Q2: label stability across a drag sequence (60 categories)', function () {
        const chart = createChart({ width: 500, height: 400 });
        chart.setOption(makeOption(60));
        const steps: any[] = [];
        // small moves, window width ~ 40%
        for (let i = 0; i <= 20; i++) {
            const start = i * 1.5;
            const end = start + 40;
            chart.dispatchAction({ type: 'dataZoom', start: start, end: end });
            const axis = xAxisOf(chart);
            const labels = axis.getViewLabels();
            const ticks = axis.getTicksCoords();
            steps.push({
                start: +start.toFixed(2),
                end: +end.toFixed(2),
                scaleExtent: axis.scale.getExtent(),
                labelCount: labels.length,
                labelTickValues: labels.map(l => l.tickValue),
                tickCount: ticks.length,
                autoInterval: innerStore(axis) ? innerStore(axis).autoInterval : null
            });
        }
        // eslint-disable-next-line
        console.log('=== Q2 drag sequence ===');
        steps.forEach(s => {
            // eslint-disable-next-line
            console.log(`win=[${s.start},${s.end}] scaleExt=[${s.scaleExtent}] `
                + `labels=${s.labelCount} ticks=${s.tickCount} autoInt=${s.autoInterval} `
                + `vals=${s.labelTickValues.join(',')}`);
        });
        chart.dispose();
    });

    it('Q3: ticks and labels always from the same extent within a render', function () {
        const chart = createChart({ width: 500, height: 400 });
        chart.setOption(makeOption(60));
        chart.dispatchAction({ type: 'dataZoom', start: 13, end: 57 });
        const axis = xAxisOf(chart);
        const labelVals = axis.getViewLabels().map(l => l.tickValue);
        const tickVals = axis.getTicksCoords().map(t => t.tickValue);
        // eslint-disable-next-line
        console.log('=== Q3 scaleExtent ===', JSON.stringify(axis.scale.getExtent()));
        // eslint-disable-next-line
        console.log('=== Q3 labelVals ===', JSON.stringify(labelVals));
        // eslint-disable-next-line
        console.log('=== Q3 tickVals ===', JSON.stringify(tickVals));
        // eslint-disable-next-line
        console.log('=== Q3 cache ===\n' + dumpCache(axis));
        chart.dispose();
    });

    it('Q4: repeated getTicksCoords/getViewLabels with 10k categories', function () {
        const chart = createChart({ width: 500, height: 400 });
        chart.setOption(makeOption(10000));
        const axis = xAxisOf(chart);
        resetCounters();
        const t0 = Date.now();
        for (let i = 0; i < 50; i++) {
            axis.getTicksCoords();
            axis.getViewLabels();
        }
        const t1 = Date.now();
        // eslint-disable-next-line
        console.log('=== Q4 50x getTicksCoords+getViewLabels ===', JSON.stringify(counters),
            'ms=' + (t1 - t0));
        // eslint-disable-next-line
        console.log('=== Q4 cache ===\n' + dumpCache(axis));

        // Now alternate two extents to see if the single-slot-per-key cache thrashes
        resetCounters();
        const t2 = Date.now();
        for (let i = 0; i < 20; i++) {
            axis.scale.setExtent(0, 9999);
            axis.getTicksCoords();
            axis.getViewLabels();
            axis.scale.setExtent(100, 5000);
            axis.getTicksCoords();
            axis.getViewLabels();
        }
        const t3 = Date.now();
        // eslint-disable-next-line
        console.log('=== Q4 alternating extents 20x2 ===', JSON.stringify(counters),
            'ms=' + (t3 - t2));
        chart.dispose();
    });

    it('Q2b: stale autoInterval when extent shrinks on the same axis object', function () {
        const chart = createChart({ width: 500, height: 400 });
        chart.setOption(makeOption(60));
        const axis = xAxisOf(chart);
        // eslint-disable-next-line
        console.log('=== Q2b full window labels ===', axis.getViewLabels().length,
            'autoInterval=', innerStore(axis) && innerStore(axis).autoInterval);
        // Simulate what dataZoom does to the scale extent without re-creating the axis.
        axis.scale.setExtent(0, 4);
        const labels = axis.getViewLabels();
        // eslint-disable-next-line
        console.log('=== Q2b narrowed to 5 categories: labels ===', labels.length,
            JSON.stringify(labels.map(l => l.tickValue)),
            'autoInterval=', innerStore(axis) && innerStore(axis).autoInterval);
        // eslint-disable-next-line
        console.log('=== Q2b freshly calculated interval for this window ===',
            axis.calculateCategoryInterval());
        chart.dispose();
    });

});

